							}
							throw err;
						}
					},
					async onRewriteQuery(query, rewriteSignal) {
						if (pendingCurates.get(callId) !== pc) throw new Error("Curator session is no longer active.");
						return rewriteSearchQuery(query, pc.summaryContext, rewriteSignal);
					},
				},
